#!/usr/bin/env python3
"""Sound effects: a library generated by synthesis (sfx/) and a per-video list of effects (videos/<name>/sfx.json).

  python3 src/vtk/sfx.py generate                               # (re)generates sfx/*.wav, deterministic
  python3 src/vtk/sfx.py marks --plan videos/<name>/plan.json   # times in the final video: segments and captions
  python3 src/vtk/sfx.py check --sfx videos/<name>/sfx.json [--plan ...]

sfx.json: [{"t": 11.0, "sound": "whoosh-short"}, {"t": 7.5, "sound": "pop-blip", "vol": 0.25}, ...]
  t   = moment in the FINAL video (after the cuts) where the effect "hits". The sound starts a little earlier
        (each sound's "hit" is in CATALOG), so the whoosh passes exactly on the cut.
  vol = optional, CATALOG default. Mixing is done by postaudio.py --sfx, before loudnorm.
Usage rules (where each sound goes): .claude/skills/sound-effects/SKILL.md.
"""
import argparse, json, os, sys, wave

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
SFX_DIR = os.path.join(ROOT, "sfx")
SR = 48000
MIN_GAP_S = 3.5  # less than this between effects feels cluttered (skill rule; was 5, lowered in the illustration test)

# hit = seconds from the start of the file to where the sound "hits"; vol = default gain in the mix
CATALOG = {
    "whoosh-short": {"hit": 0.11, "vol": 0.28, "use": "transition: change of topic or slide"},
    "pop-bubble":   {"hit": 0.02, "vol": 0.30, "use": "soft highlight: text or idea appearing"},
    "pop-wood":     {"hit": 0.0,  "vol": 0.30, "use": "dry highlight: punchline"},
    "pop-blip":     {"hit": 0.01, "vol": 0.25, "use": "light highlight: list item, number"},
    "click":        {"hit": 0.0,  "vol": 0.35, "use": "on-screen action: click, button, sending a prompt"},
}


# ---------- synthesis (numpy only here, so the rest of the module doesn't depend on it) ----------

def _synthesize():
    import numpy as np
    rng = np.random.default_rng(7)

    def norm(x, peak_db):
        x = x / (np.max(np.abs(x)) + 1e-9) * 10 ** (peak_db / 20)
        f = int(0.004 * SR); x[-f:] *= np.linspace(1, 0, f)
        return x

    def tone(dur, f, tau, att=0.002):
        n = int(dur * SR); t = np.arange(n) / SR
        ff = f(t) if callable(f) else np.full(n, float(f))
        return np.sin(2 * np.pi * np.cumsum(ff) / SR) * (1 - np.exp(-t / att)) * np.exp(-t / tau)

    def whoosh(dur, f0, f1, q=1.2, attack=0.5):
        n = int(dur * SR); t = np.linspace(0, 1, n)
        env = np.where(t < attack, (t / attack) ** 2, ((1 - t) / (1 - attack)) ** 1.5)
        x = rng.standard_normal(n); fc = np.geomspace(f0, f1, n)
        y = np.zeros(n); x1 = x2 = y1 = y2 = 0.0
        for i in range(n):  # band-pass (biquad) with the center frequency sweeping f0 -> f1
            w0 = 2 * np.pi * fc[i] / SR; al = np.sin(w0) / (2 * q); a0 = 1 + al
            yi = (al * x[i] - al * x2 + 2 * np.cos(w0) * y1 - (1 - al) * y2) / a0
            x2, x1, y2, y1 = x1, x[i], y1, yi; y[i] = yi
        return y * env

    t08 = np.arange(int(0.08 * SR)) / SR
    t03 = np.arange(int(0.03 * SR)) / SR
    return {
        "whoosh-short": norm(whoosh(0.22, 600, 5000), -3),
        "pop-bubble": norm(tone(0.12, lambda t: 380 + 520 * (1 - np.exp(-t / 0.02)), 0.03, 0.004), -6),
        "pop-wood": norm(tone(0.08, 520, 0.018) + 0.5 * tone(0.08, 1320, 0.008)
                         + 0.15 * rng.standard_normal(len(t08)) * np.exp(-t08 / 0.0015), -6),
        "pop-blip": norm(tone(0.10, 700, 0.035, 0.006), -8),
        "click": norm(np.sin(2 * np.pi * 3200 * t03) * np.exp(-t03 / 0.003)
                      + 0.6 * rng.standard_normal(len(t03)) * np.exp(-t03 / 0.0012), -6),
    }


def generate(out=SFX_DIR):
    os.makedirs(out, exist_ok=True)
    for name, x in _synthesize().items():
        with wave.open(os.path.join(out, name + ".wav"), "wb") as w:
            w.setnchannels(1); w.setsampwidth(2); w.setframerate(SR)
            w.writeframes((x * 32767).astype("<i2").tobytes())
        print("ok", name)


# ---------- per-video list ----------

def timeline(plan):
    """plan.json -> [(start_in_final, end_in_final, segment)]: where each segment lands in the final video."""
    out, t = [], 0.0
    for c in plan:
        d = c["e"] - c["s"]; out.append((round(t, 3), round(t + d, 3), c)); t += d
    return out


def check(cues, duration=None):
    """List of problems (empty = ok): unknown sound, outside the video, effects too close together."""
    errors = []
    for i, c in enumerate(cues):
        if c.get("sound") not in CATALOG:
            errors.append(f"#{i}: sound '{c.get('sound')}' does not exist (options: {', '.join(CATALOG)})")
        if not isinstance(c.get("t"), (int, float)) or c["t"] < 0 or (duration and c["t"] > duration):
            errors.append(f"#{i}: t={c.get('t')} outside the video")
        v = c.get("vol")
        if v is not None and not (0 < v <= 1):
            errors.append(f"#{i}: vol={v} outside (0, 1]")
    ts = sorted(c["t"] for c in cues if isinstance(c.get("t"), (int, float)))
    for a, b in zip(ts, ts[1:]):
        if b - a < MIN_GAP_S:
            errors.append(f"effects at {a:.1f}s and {b:.1f}s: less than {MIN_GAP_S:g}s apart")
    return errors


def mix_filter(cues, voice="[voice]", first_input=1, output="[mix]"):
    """-filter_complex fragment: delays each effect to its t (minus the hit) and mixes it with the voice.
    The effects come in as inputs first_input, first_input+1, ... in the order of `cues`."""
    parts, labels = [], []
    for i, c in enumerate(cues):
        cat = CATALOG[c["sound"]]
        ms = max(0, int(round((c["t"] - cat["hit"]) * 1000)))
        parts.append(f"[{first_input + i}:a]adelay={ms}:all=1,volume={c.get('vol', cat['vol'])}[s{i}]")
        labels.append(f"[s{i}]")
    parts.append(f"{voice}{''.join(labels)}amix=inputs={len(cues) + 1}:normalize=0:duration=first{output}")
    return ";".join(parts)


def path(sound):
    return os.path.join(SFX_DIR, sound + ".wav")


def main():
    ap = argparse.ArgumentParser(); sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("generate")
    m = sub.add_parser("marks"); m.add_argument("--plan", required=True)
    c = sub.add_parser("check"); c.add_argument("--sfx", required=True); c.add_argument("--plan")
    a = ap.parse_args()
    if a.cmd == "generate":
        generate(); return
    if a.cmd == "marks":
        for n, (u, v, c) in enumerate(timeline(json.load(open(a.plan, encoding="utf-8")))):
            print(f"segment {n:02d}  {u:7.2f}s - {v:7.2f}s")
            for (x0, _, txt) in c["ev"]:
                print(f"    {u + x0:7.2f}s  {txt}")
        return
    cues = json.load(open(a.sfx, encoding="utf-8"))
    dur = timeline(json.load(open(a.plan, encoding="utf-8")))[-1][1] if a.plan else None
    errors = check(cues, dur)
    for e in errors: print("ERROR", e)
    if errors: sys.exit(1)
    print(f"ok: {len(cues)} effects")


if __name__ == "__main__":
    main()
